CLAIM_ID='SFT-ENG-PHYSICAL-HANDOFF-001'; DOMAINS=(('answer-only-or-unversioned-artifact', 'physical-law-component-environment-carrier'), ('operating-test-or-lifecycle-boundary-erased', 'physical-design-bounded'), ('target-fitted-status-or-application-selected-relation', 'law-to-physical-implementation-relation'), ('successful-output-only', 'law-receipts-materials-geometry-boundary-measurements-and-failures-held'), ('law-design-test-simulation-demonstration-conflated', 'science-design-test-and-decision-classes-explicit'), ('opaque-build-prior-output-or-authority-selected', 'root-bound-forward-translation'), ('single-platform-prototype-or-favourable-run-universalized', 'positive-finite-extension-preserves-platforms-failures-and-versions'), ('free-weight-exception-or-silent-dependency', 'no-extra-rule')); SURVIVOR='physical-law-component-environment-carrier__physical-design-bounded__law-to-physical-implementation-relation__law-receipts-materials-geometry-boundary-measurements-and-failures-held__science-design-test-and-decision-classes-explicit__root-bound-forward-translation__positive-finite-extension-preserves-platforms-failures-and-versions__no-extra-rule'
def main():
    sealed=json.load(open(sys.argv[1],encoding="utf-8")); generated=["__".join(x) for x in product(*DOMAINS)]; received=[x["candidate_id"] for x in sealed["census"]["candidates"]]; decisions={x["candidate_id"]:x["survives"] for x in sealed["decisions"]}
    passed=(sealed["claim_id"]==CLAIM_ID and received==generated and sealed["census"]["expected_cardinality"]==len(generated) and len(set(received))==len(generated) and decisions=={x:x==SURVIVOR for x in generated} and sum(decisions.values())==1 and sealed["closure"]["scope"]=="depth_independent" and sealed["closure"]["minimality_passed"] is True and sealed["closure"]["named_shape_uniqueness_passed"] is True and {x["kind"] for x in sealed["controls"]}=={"false_premise","tampered_source","tampered_artifact","boundary"} and all(x["passed"] is True for x in sealed["controls"]))
    print(json.dumps({"validated_seal_hash":sealed["seal_hash"],"recomputed_from_declared_inputs":True,"passed":passed,"certificate":{"claim_id":CLAIM_ID,"candidate_count":len(generated),"survivor":SURVIVOR if passed else None}},sort_keys=True))
